//! Item ids that server emulators (ServUO, ModernUO) treat as wearable, with the layer their scripts
//! give them. Generated by `tools/gen_wearables.py` into `data/wearables.txt`.
//!
//! The tiledata also says which items are wearable and in which layer (flag + `quality`), but it is
//! not always right and lags behind the newest clients (issue #7), so the paperdoll uses both: this
//! list is a *suggestion* ("known wearable"), never a restriction.

use std::collections::HashMap;
use std::sync::OnceLock;

const DATA: &str = include_str!("../data/wearables.txt");

/// Item id -> the layer the emulator scripts set (`None`: they do not name one, the tiledata decides).
pub fn emulator_wearables() -> &'static HashMap<u16, Option<u8>> {
    static MAP: OnceLock<HashMap<u16, Option<u8>>> = OnceLock::new();
    MAP.get_or_init(|| parse(DATA))
}

fn parse(text: &str) -> HashMap<u16, Option<u8>> {
    let mut map = HashMap::new();
    for line in text.lines().filter(|l| !l.starts_with('#') && !l.trim().is_empty()) {
        let mut parts = line.split_whitespace();
        let (Some(id), Some(layer)) = (parts.next(), parts.next()) else { continue };
        let Ok(id) = u16::from_str_radix(id.trim_start_matches("0x"), 16) else { continue };
        // an id listed with a layer wins over one listed without
        let layer = layer.parse::<u8>().ok();
        let entry = map.entry(id).or_insert(layer);
        if entry.is_none() {
            *entry = layer;
        }
    }
    map
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_embedded_list_parses() {
        let m = emulator_wearables();
        assert!(m.len() > 300, "{} entries", m.len());
        assert_eq!(m.get(&0x1517), Some(&Some(5))); // shirt
        assert_eq!(m.get(&0x13BB), Some(&None)); // chain coif: layer comes from the tiledata
        assert!(!m.contains_key(&0x2662)); // the museum decoration is not in any emulator's equipment
    }

    #[test]
    fn a_layer_wins_over_no_layer() {
        let m = parse("# c\n0x0001 - A x\n0x0001 5 B y\n0x0002 3 A z\n0x0002 - B w\nbad line\n");
        assert_eq!(m[&1], Some(5));
        assert_eq!(m[&2], Some(3));
    }
}
